function (zaciatok, koniec) {  
    if (!zaciatok || !koniec) {
      return '';
    }

    var diffTime = koniec - zaciatok;
    var diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1; 

	return diffDays;
}

function diffMonths(start, end) {
  if (!(start instanceof Date) || !(end instanceof Date)) return 0;
  if (end < start) return 0;

  let lastDayInMonth = function(year, month) {
  	var date = new Date(year, month, 0);
    return date.getDate();
  }


  let years = end.getFullYear() - start.getFullYear();
  let months = end.getMonth() - start.getMonth();
  let total = years * 12 + months;

  if (lastDayInMonth(end.getFullYear(), end.getMonth() + 1) === end.getDate() && start.getDate() === 1) {
     total++; 
  }

  return total;
}

function(b0, b1, b2, b3, b4, b5) {
