let totalSumA = Number(tag('rozpocet.kalkulacka.typ_kalkulacky.bez_partnerov.vydavky[_].spolu.rozpocet_a'));
let maxSum = Number(tag('rozpocet.max_vyska'));
let minSum = Number(tag('rozpocet.min_vyska'));

if (totalSumA < minSum) {
	return `Rozpočet typ A: Rozpočet pre malé granty môže byť maximálne ${maxSum} €`;    
}
if (totalSumA > maxSum) {
	return `Rozpočet typ A: Rozpočet pre malé granty môže byť maximálne ${maxSum} €`;    
}
return totalSumA >= minSum && totalSumA <= maxSum;

